<?php
session_start();
if (!isset($_SESSION['user_id']) || ($_SESSION['role'] ?? '') !== 'student') { header('Location: ../login.php'); exit(); }
require_once '../config/db.php';
require_once '../includes/module_helpers.php';
$studentPhoto = '';
if (ensureAdminProfileTable($conn)) {
    $profileStmt = $conn->prepare('SELECT photo_path, space_label FROM admin_profiles WHERE user_id = ?');
    $profileStmt->bind_param('i', $_SESSION['user_id']);
    $profileStmt->execute();
    $studentProfile = $profileStmt->get_result()->fetch_assoc() ?? [];
    $studentPhoto = $studentProfile['photo_path'] ?? '';
    $studentSpaceLabel = $studentProfile['space_label'] ?? 'Your student space';
    $profileStmt->close();
}
if (!isset($studentSpaceLabel)) $studentSpaceLabel = 'Your student space';
?>
